style.css:
@-moz-document domain("bandlab.com") {
/* General body and background */
  body, .sc-eCImPb, .sc-hmdomO {
    background-color: #f5f0d6 !important; /* softer muted yellow-beige */
    color: #3a2f1a !important; /* dark retro brown text */
  }

  /* Make all text retro brown */
  * {
    color: #3a2f1a !important;
    background-color: transparent !important;
    box-shadow: none !important;
  }

  /* Outlines for buttons */
  button, .sc-eDvSVe, .sc-dxgOiQ, .sc-jSMfEi, .sc-kLgntA {
    border: 1px solid #d4b84c !important; /* darker gold border */
    background-color: #e6d267 !important; /* muted retro yellow */
    color: #2a1e0d !important;
    border-radius: 6px !important;
  }

  /* Inputs and dropdowns */
  input, select, textarea {
    background-color: #f0e6b8 !important; /* parchment yellow */
    color: #2a1e0d !important;
    border: 1px solid #d4b84c !important;
  }

  /* Remove background images or shadows */
  [style*="background-image"], [class*="background"] {
    background: none !important;
  }

  /* Sliders, knobs, etc. */
  .sc-hGoxap, .sc-hlTVkV {
    background-color: #e6d267 !important;
    border: 1px solid #d4b84c !important;
  }

  /* Hover effects */
  button:hover, .sc-dxgOiQ:hover {
    background-color: #d9b94f !important; /* deeper golden hover */
    color: #2a1e0d !important;
    border-color: #bfa63d !important;
  }

  /* Scrollbars */
  ::-webkit-scrollbar {
    width: 8px;
  }
  ::-webkit-scrollbar-track {
    background: #f5f0d6;
  }
  ::-webkit-scrollbar-thumb {
    background: #d4b84c;
    border-radius: 4px;
  }

  /* Logos / icons retro tint */
  img, svg, .logo, .sc-jIAOiI {
    filter: sepia(50%) saturate(100%) brightness(95%) !important;
  }
}
